export function detectLang() {
  try {
    const saved = localStorage.getItem('pawse.lang');
    if (saved && LANGS.includes(saved)) return saved;
  } catch {
    /* storage unavailable */
  }
  const nav = typeof navigator !== 'undefined' ? navigator.language || '' : '';
  return nav.toLowerCase().startsWith('zh') ? 'zh' : 'en';
}

export function saveLang(lang) {
  try {
    localStorage.setItem('pawse.lang', lang);
  } catch {
    /* ignore */
  }
}
// Central switches. Set them in .env.local (see .env.example).
// import.meta.env is undefined outside Vite (e.g. plain-Node checks), so guard it.
const env = (typeof import.meta !== 'undefined' && import.meta.env) || {};

const param = (k) => {
  try {
    return new URLSearchParams(window.location.search).get(k);
  } catch {
    return null;
  }
};

/** 'mock' = scripted demo (default). 'live' = the Pawse backend. "?live=1" in the URL switches all three at runtime. */
const DEMO_ALL = param('demo') === '1';
const LIVE_ALL = !DEMO_ALL && param('live') === '1';
export const VOICE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_VOICE_AGENT || 'mock';
export const CLINIC_SEARCH = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_CLINIC_SEARCH || 'mock';
export const PHONE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_PHONE_AGENT || 'mock';

export const VOICE_AGENT_URL = env.VITE_VOICE_AGENT_URL || '';
export const CLINIC_SEARCH_URL = env.VITE_CLINIC_SEARCH_URL || '';
export const PHONE_AGENT_URL = env.VITE_PHONE_AGENT_URL || '';

/** Mock playback speed. "?speed=3" in the URL plays the demo 3x faster (handy for rehearsing). */
export const MOCK_SPEED = (() => {
  const v = Number(param('speed'));
  return v > 0 ? v : 1;
})();

import { useEffect, useState } from 'react';
import Home from './pages/Home.jsx';
import VoiceCall from './pages/VoiceCall.jsx';
import ClinicList from './pages/ClinicList.jsx';
import LiveHandoff from './pages/LiveHandoff.jsx';
import PhoneCall from './pages/PhoneCall.jsx';
import Plan from './pages/Plan.jsx';
import { strings, detectLang, saveLang } from './i18n.js';
import { primeSpeech } from './agents/speech.js';
import { buildSummary } from './utils/summary.js';
import { IS_LIVE_PHONE } from './agents/index.js';
import { PHONE_AGENT_URL } from './config.js';

const GRADIUM_KEY = 'pawse.gradium';
function loadGradiumChoice() {
  try {
    return localStorage.getItem(GRADIUM_KEY) !== '0'; // on by default, the owner can turn it off
  } catch {
    return true;
  }
}

// home → voice call with Pawse → advice
//   → "call the vet": clinic list → Pawse calls the chosen clinic
//   → "call the insurer": Pawse calls the insurer
//   → plan (summary)
export default function App() {
  const [view, setView] = useState('home'); // home | voice | clinics | phone | plan
  const [lang, setLangState] = useState(detectLang);
  const [triage, setTriage] = useState(null);
  const [vet, setVet] = useState(null);
  const [insurance, setInsurance] = useState(null);
  const [clinic, setClinic] = useState(null);
  const [target, setTarget] = useState(null);
  const [rehearsal, setRehearsal] = useState(false);
  const [gradiumOn, setGradiumOnState] = useState(loadGradiumChoice);
  const [voiceStatus, setVoiceStatus] = useState(null);

  const setGradiumOn = (on) => {
    setGradiumOnState(on);
    try {
      localStorage.setItem(GRADIUM_KEY, on ? '1' : '0');
    } catch {
      /* storage unavailable */
    }
  };

  // Live phone calls only: is Gradium configured, and does this session have its own German voice?
  useEffect(() => {
    if (!IS_LIVE_PHONE) return undefined;
    let alive = true;
    fetch(`${PHONE_AGENT_URL || ''}/api/v1/voice/status`)
      .then((r) => (r.ok ? r.json() : null))
      .then((s) => alive && s && setVoiceStatus(s))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);
  // Unknown status: still offer Gradium; the call falls back to the browser voice on 503.
  const gradiumAvailable = IS_LIVE_PHONE && (!voiceStatus || voiceStatus.gradium_configured === true);
  const ownVoice = !!(voiceStatus && voiceStatus.my_voice_ready);

  const t = strings[lang] || strings.en;
  const Handoff = IS_LIVE_PHONE && !rehearsal ? LiveHandoff : PhoneCall;

  const setLang = (l) => {
    setLangState(l);
    saveLang(l);
  };

  useEffect(() => {
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
  }, [lang]);

  const startCall = () => {
    primeSpeech(); // unlock speech on iOS while we are inside the tap
    setTriage(null);
    setVet(null);
    setInsurance(null);
    setClinic(null);
    setView('voice');
  };

  const call = (to) => {
    setRehearsal(false);
    primeSpeech();
    if (to === 'vet') {
      setView('clinics');
      return;
    }
    setTarget(to);
    setView('phone');
  };

  const pickClinic = (c) => {
    setRehearsal(false);
    primeSpeech();
    setClinic(c);
    setTarget('vet');
    setView('phone');
  };

  const callDone = (result) => {
    if (result && target === 'vet') setVet(result);
    if (result && target === 'insurance') setInsurance(result);
    setView(triage ? 'plan' : 'home');
  };

  if (view === 'voice') {
    return (
      <VoiceCall
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onTriage={setTriage}
        onCall={call}
        onEnd={() => setView(triage ? 'plan' : 'home')}
      />
    );
  }
  if (view === 'clinics') {
    // Going back from the list never restarts the voice call: show the plan instead.
    return <ClinicList t={t} lang={lang} triage={triage} onPick={pickClinic} onBack={() => setView(triage ? 'plan' : 'home')} />;
  }
  if (view === 'phone') {
    return (
      <Handoff
        key={`${target}-${clinic ? clinic.id : ''}`}
        t={t}
        lang={lang}
        target={target}
        clinic={target === 'vet' ? clinic : null}
        gradium={gradiumAvailable ? { on: gradiumOn, ownVoice, set: setGradiumOn } : null}
        context={{
          gradiumConsent: gradiumAvailable && gradiumOn,
          voice: ownVoice ? 'my_voice' : 'standard',
          summary: buildSummary({ lang, triage, vet, insurance }),
          clinic: target === 'vet' ? clinic : undefined,
          estimate: vet ? vet.estimate : undefined,
        }}
        onDone={callDone}
        onRehearse={() => { setGradiumOn(false); setRehearsal(true); }}
      />
    );
  }
  if (view === 'plan' && triage) {
    return (
      <Plan
        t={t}
        lang={lang}
        triage={triage}
        vet={vet}
        insurance={insurance}
        onCall={call}
        onRestart={() => setView('home')}
      />
    );
  }
  return <Home t={t} lang={lang} setLang={setLang} onStart={startCall} />;
}
// Tiny wrapper around the browser's built-in text-to-speech, used ONLY by the mock agents
// so the demo actually talks. The live agents play their own audio.

const hasTTS = () =>
  typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined';

let muted = false;
try {
  muted = localStorage.getItem('pawse.muted') === '1';
} catch {
  /* storage unavailable */
}

export const isSpeechMuted = () => muted;

export function setSpeechMuted(m) {
  muted = !!m;
  try {
    localStorage.setItem('pawse.muted', muted ? '1' : '0');
  } catch {
    /* ignore */
  }
  if (muted && hasTTS()) window.speechSynthesis.cancel();
}

/** Rough spoken duration, used for pacing when the voice is muted or unavailable. */
export function estimateMs(text, lang) {
  const per = String(lang).startsWith('zh') ? 210 : 68;
  return Math.max(1200, String(text).length * per);
}

const TAGS = { zh: 'zh-CN', en: 'en-US', de: 'de-DE', hi: 'hi-IN' };

function pickVoice(tag) {
  const voices = window.speechSynthesis.getVoices();
  return voices.find((v) => v.lang === tag) || voices.find((v) => v.lang.toLowerCase().startsWith(tag.slice(0, 2)));
}

/** Call inside a tap so iOS Safari allows speech later on. */
export function primeSpeech() {
  if (!hasTTS()) return;
  try {
    const u = new SpeechSynthesisUtterance(' ');
    u.volume = 0;
    window.speechSynthesis.speak(u);
  } catch {
    /* ignore */
  }
}

export function stopSpeech() {
  if (hasTTS()) window.speechSynthesis.cancel();
}

/** Speak `text`; resolves when finished. speed > 1 (tests / rehearsal) skips the voice. */
export function speak(text, lang, { speed = 1, pitch = 1, rate = 1 } = {}) {
  const est = estimateMs(text, lang);
  if (speed > 1 || muted || !hasTTS()) return new Promise((r) => setTimeout(r, est / speed));

  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      clearTimeout(guard);
      resolve();
    };
    const guard = setTimeout(finish, est * 2 + 3000); // never hang if the engine stalls
    try {
      const u = new SpeechSynthesisUtterance(text);
      const tag = TAGS[lang] || lang;
      u.lang = tag;
      const v = pickVoice(tag);
      if (v) u.voice = v;
      u.pitch = pitch;
      u.rate = rate;
      u.onend = finish;
      u.onerror = finish;
      window.speechSynthesis.speak(u);
    } catch {
      setTimeout(finish, est);
    }
  });
}
// Scripted phone call: Pawse calls the vet or the insurer in German, with a live translation.
// Implements the PHONE AGENT contract in ../contracts.js.

import { phoneScripts, buildVetResult, buildInsuranceResult, DEFAULT_ESTIMATE } from './mockScripts.js';
import { speak, stopSpeech } from './speech.js';

export function createMockPhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
  const script = phoneScripts[target] || phoneScripts.vet;
  const L = (o) => o[lang] ?? o.en;
  const listeners = new Set();
  const timers = new Set();
  let started = false;
  let ended = false;

  const emit = (e) => {
    if (!ended) listeners.forEach((l) => l(e));
  };
  const wait = (ms) =>
    new Promise((resolve) => {
      const id = setTimeout(() => {
        timers.delete(id);
        resolve();
      }, ms / speed);
      timers.add(id);
    });

  async function run() {
    emit({ type: 'status', state: 'dialing' });
    await wait(2400);
    if (ended) return;
    emit({ type: 'status', state: 'connected' });
    for (const line of script.lines) {
      await wait(450);
      if (ended) return;
      emit({ type: 'speaking', who: line.who });
      emit({ type: 'line', who: line.who, original: line.de, text: L(line.text) });
      await speak(line.de, 'de', { speed, pitch: line.who === 'callee' ? 0.8 : 1.15 });
      if (ended) return;
      emit({ type: 'speaking', who: 'none' });
    }
    await wait(500);
    if (ended) return;
    const result =
      target === 'insurance'
        ? buildInsuranceResult(lang, typeof context.estimate === 'number' ? context.estimate : DEFAULT_ESTIMATE)
        : buildVetResult(lang, context.clinic);
    emit({ type: 'result', ...result });
    emit({ type: 'status', state: 'ended' });
  }

  return {
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started) return;
      started = true;
      run();
    },
    hangup() {
      if (ended) return;
      emit({ type: 'status', state: 'ended' });
      ended = true;
      timers.forEach(clearTimeout);
      timers.clear();
      stopSpeech();
    },
  };
}
